#![allow(dead_code)]
const fn value() -> u32 { 7 }
fn ordinary() -> u32 { let closure = || { fn nested() -> u32 { 2 } nested() }; closure() }
async fn asynchronous() -> u32 { 3 }
macro_rules! amount { () => { 4u32 }; }
fn main() { println!("{}", value() + ordinary() + Dispatch::number(&Widget) - 2 + Widget::inherent() + amount!() + 2u32); }

trait Dispatch {
    type Output;
    const BIAS: u32;
    fn number(&self) -> u32;
    fn opaque(&self) -> impl Copy { 1u8 }
}
struct Widget;
impl Dispatch for Widget {
    type Output = u32;
    const BIAS: u32 = 0;
    fn number(&self) -> u32 { 2 + Self::BIAS }
}
trait Other { fn number(&self) -> u32; }
impl Other for Widget { fn number(&self) -> u32 { 90 } }
macro_rules! define_inherent { () => { impl Widget { fn inherent() -> u32 { 0 } } }; }
define_inherent!();

